import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import MainLayout from './layouts/MainLayout';
import Dashboard from './pages/Dashboard';

// Import Dashboards
import ATSModule from './pages/ATS/ATSModule';
import InsuranceModule from './pages/Insurance/InsuranceModule';
import WorkspacePage from './pages/Workspace/WorkspacePage';
import SecurityPage from './pages/Security/SecurityPage';
import CloudPage from './pages/CloudInfra/CloudPage';

// Import ATS Sub-pages
import ATS_P1 from './pages/ATS/ATS_P1';
import ATS_P2 from './pages/ATS/ATS_P2';
import ATS_P3 from './pages/ATS/ATS_P3';
import ATS_P4 from './pages/ATS/ATS_P4';

// Import Insurance Sub-pages
import Ins_P1 from './pages/Insurance/Ins_P1';
import Ins_P2 from './pages/Insurance/Ins_P2';
import Ins_P3 from './pages/Insurance/Ins_P3';
import Ins_P4 from './pages/Insurance/Ins_P4';

// Import Workspace Sub-pages
import Work_P1 from './pages/Workspace/Work_P1';
import Work_P2 from './pages/Workspace/Work_P2';
import Work_P3 from './pages/Workspace/Work_P3';
import Work_P4 from './pages/Workspace/Work_P4';

// Import Security Sub-pages
import Sec_P1 from './pages/Security/Sec_P1';
import Sec_P2 from './pages/Security/Sec_P2';
import Sec_P3 from './pages/Security/Sec_P3';
import Sec_P4 from './pages/Security/Sec_P4';

// Import Cloud Sub-pages
import Cloud_P1 from './pages/CloudInfra/Cloud_P1';
import Cloud_P2 from './pages/CloudInfra/Cloud_P2';
import Cloud_P3 from './pages/CloudInfra/Cloud_P3';
import Cloud_P4 from './pages/CloudInfra/Cloud_P4';

function App() {
  return (
    <Router>
      <Routes>
        {/* Main Context Framework Provider Wrapper */}
        <Route path="/" element={<MainLayout />}>
          <Route index element={<Dashboard />} />
          
          {/* Main Dashboard Modules */}
          <Route path="ats" element={<ATSModule />} />
          <Route path="ins" element={<InsuranceModule />} />
          <Route path="work" element={<WorkspacePage />} />
          <Route path="sec" element={<SecurityPage />} />
          <Route path="cloud" element={<CloudPage />} />

          {/* Legacy Fallbacks */}
          <Route path="flagship1" element={<ATSModule />} />
          <Route path="flagship2" element={<InsuranceModule />} />
          <Route path="flagship3" element={<WorkspacePage />} />
          <Route path="flagship4" element={<SecurityPage />} />
          <Route path="flagship5" element={<CloudPage />} />

          {/* ATS Sub-routes explicitly declared */}
          <Route path="ats/p1" element={<ATS_P1 />} />
          <Route path="ats/p2" element={<ATS_P2 />} />
          <Route path="ats/p3" element={<ATS_P3 />} />
          <Route path="ats/p4" element={<ATS_P4 />} />

          {/* Insurance Sub-routes explicitly declared */}
          <Route path="ins/p1" element={<Ins_P1 />} />
          <Route path="ins/p2" element={<Ins_P2 />} />
          <Route path="ins/p3" element={<Ins_P3 />} />
          <Route path="ins/p4" element={<Ins_P4 />} />

          {/* Workspace Sub-routes explicitly declared */}
          <Route path="work/p1" element={<Work_P1 />} />
          <Route path="work/p2" element={<Work_P2 />} />
          <Route path="work/p3" element={<Work_P3 />} />
          <Route path="work/p4" element={<Work_P4 />} />

          {/* Security Sub-routes explicitly declared */}
          <Route path="sec/p1" element={<Sec_P1 />} />
          <Route path="sec/p2" element={<Sec_P2 />} />
          <Route path="sec/p3" element={<Sec_P3 />} />
          <Route path="sec/p4" element={<Sec_P4 />} />

          {/* Cloud Sub-routes explicitly declared */}
          <Route path="cloud/p1" element={<Cloud_P1 />} />
          <Route path="cloud/p2" element={<Cloud_P2 />} />
          <Route path="cloud/p3" element={<Cloud_P3 />} />
          <Route path="cloud/p4" element={<Cloud_P4 />} />

        </Route>
      </Routes>
    </Router>
  );
}

export default App;
